function scroll(item,entry){const duration=milliseconds(entry.easing,entry.duration),rect=item.el.getBoundingClientRect();let parent=item.el.parentElement;while(parent&&parent!==host.viewport){const style=getComputedStyle(parent);if(/auto|scroll/.test(style.overflowY+style.overflowX))break;parent=parent.parentElement}parent=parent||host.viewport;const root=parent.getBoundingClientRect();const scaleX=root.width/parent.offsetWidth||1,scaleY=root.height/parent.offsetHeight||1;const top=parent.scrollTop+(rect.top-root.top)/scaleY,left=parent.scrollLeft+(rect.left-root.left)/scaleX;const options={behavior:duration?'smooth':'instant'};if(entry.direction===1||entry.direction===2)options.top=Math.max(0,top);if(entry.direction===0||entry.direction===2)options.left=Math.max(0,left);parent.scrollTo(options)}
